-- The schema the migrations in migrations/ produce. Generated by
-- TestSchema; do not edit. Refresh it after adding a migration:
--   go test ./internal/store -run TestSchema -update

CREATE TABLE api_tokens (
    -- A UUIDv7: the handle the user sees and revokes the token by.
    id TEXT PRIMARY KEY CHECK (length(id) = 36),
    -- The hex SHA-256 of the token.
    token_hash TEXT NOT NULL CHECK (length(token_hash) = 64),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- What the user calls it, such as "iPhone" or "Claude".
    name TEXT NOT NULL CHECK (name <> ''),
    -- What it may do: scopes separated by spaces (ingest, tools, read).
    scopes TEXT NOT NULL CHECK (scopes <> ''),
    created_at TEXT NOT NULL,
    -- When it was last used, to the hour or so; NULL until its first use.
    last_used_at TEXT
) STRICT;

CREATE UNIQUE INDEX api_tokens_token_hash ON api_tokens (token_hash);

CREATE INDEX api_tokens_user_id ON api_tokens (user_id);

CREATE TABLE schema_migrations (
	version    INTEGER PRIMARY KEY,
	name       TEXT    NOT NULL,
	checksum   TEXT    NOT NULL,
	applied_at TEXT    NOT NULL
) STRICT;

CREATE TABLE sessions (
    -- The hex SHA-256 of the session token.
    id TEXT PRIMARY KEY CHECK (length(id) = 64),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    -- When the user last used the session, to the hour or so: the server
    -- updates it at most once an hour.
    last_seen_at TEXT NOT NULL,
    -- The session ends here however active it is; the user signs in again.
    expires_at TEXT NOT NULL
) STRICT;

CREATE INDEX sessions_expires_at ON sessions (expires_at);

CREATE INDEX sessions_user_id ON sessions (user_id);

CREATE TABLE user_identities (
    issuer TEXT NOT NULL CHECK (issuer <> ''),
    subject TEXT NOT NULL CHECK (subject <> ''),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    PRIMARY KEY (issuer, subject)
) STRICT;

CREATE UNIQUE INDEX user_identities_user_issuer ON user_identities (user_id, issuer);

CREATE TABLE users (
    -- A UUIDv7, in the canonical text form.
    id TEXT PRIMARY KEY CHECK (length(id) = 36),
    -- The sign-in name, in the form user.NormalizeEmail gives it.
    email TEXT NOT NULL CHECK (email <> ''),
    name TEXT NOT NULL CHECK (name <> ''),
    role TEXT NOT NULL CHECK (role IN ('admin', 'user')),
    -- An argon2id hash in the PHC string format. NULL means the user
    -- cannot sign in with a password (single sign-on comes later).
    password_hash TEXT,
    locale TEXT NOT NULL CHECK (locale <> ''),
    timezone TEXT NOT NULL CHECK (timezone <> ''),
    -- The hour at which the user's day starts: a meal before it belongs
    -- to the day before.
    day_start_hour INTEGER NOT NULL CHECK (day_start_hour BETWEEN 0 AND 23),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
) STRICT;

CREATE UNIQUE INDEX users_email ON users (email);
